static class NativeInstall {
static string Hash(string file){using(var h=SHA256.Create())using(var stream=File.OpenRead(file))return BitConverter.ToString(h.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
public static void Run(string folder,bool shortcut,bool launch){string target=Path.GetFullPath(folder),prefix=target.TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;foreach(Process p in Process.GetProcessesByName("OreumMok")){try{if(Path.GetFullPath(p.MainModule.FileName)==Path.Combine(target,"OreumMok.exe"))throw new InvalidOperationException("���� ���� �������� ���� �� �ٽ� ��ġ�ϼ���.");}catch(InvalidOperationException){throw;}catch{}}
using(Stream checkStream=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip"))using(var checkZip=new ZipArchive(checkStream,ZipArchiveMode.Read)){foreach(var entry in checkZip.Entries){string file=Path.GetFullPath(Path.Combine(target,entry.FullName));if(!file.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))throw new Exception("��ġ ���� ��� ����");if(File.Exists(file)){try{using(var handle=File.Open(file,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){} }catch(IOException){throw new IOException("���� ������ â�� ��� ���� �� �ٽ� ��ġ�ϼ���. ���� ���� ����: "+Path.GetFileName(file));}}}}Directory.CreateDirectory(target);string backup=Path.Combine(target,"upgrade-backups",DateTime.Now.ToString("yyyyMMdd-HHmmss"));using(Stream embedded=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip"))using(var zip=new ZipArchive(embedded,ZipArchiveMode.Read)){foreach(var entry in zip.Entries){string destination=Path.GetFullPath(Path.Combine(target,entry.FullName));if(!destination.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))throw new Exception("��ġ ���� ��� ����");if(entry.FullName.EndsWith("/")){Directory.CreateDirectory(destination);continue;}Directory.CreateDirectory(Path.GetDirectoryName(destination));if(File.Exists(destination)){Directory.CreateDirectory(Path.GetDirectoryName(Path.Combine(backup,entry.FullName)));File.Copy(destination,Path.Combine(backup,entry.FullName),true);}using(var input=entry.Open())using(var output=File.Create(destination))input.CopyTo(output);}}
var json=new JavaScriptSerializer();var hashes=json.Deserialize<System.Collections.Generic.Dictionary<string,string>>(File.ReadAllText(Path.Combine(target,"native-checksums.json")));foreach(var pair in hashes){string f=Path.GetFullPath(Path.Combine(target,pair.Key));if(!f.StartsWith(prefix,StringComparison.OrdinalIgnoreCase)||Hash(f)!=pair.Value)throw new Exception("��ġ ���� ����: "+pair.Key);}if(shortcut){Type type=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(type);string desktop=Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);dynamic link=shell.CreateShortcut(Path.Combine(desktop,"������.lnk"));link.TargetPath=Path.Combine(target,"OreumMok.exe");link.WorkingDirectory=target;link.IconLocation=Path.Combine(target,"oreummok.ico")+",0";link.Description="������ ����Ƽ�� ����ũ�� ��";link.Save();}File.WriteAllText(Path.Combine(target,"installation-result.json"),json.Serialize(new{version="0.10.0",native=true,verified=true,installed=DateTime.Now.ToString("o"),target=target}));if(launch)Process.Start(new ProcessStartInfo(Path.Combine(target,"OreumMok.exe")){WorkingDirectory=target});}
[STAThread]static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{if(args.Contains("--silent")){string flag=args.FirstOrDefault(x=>x.StartsWith("--target="));if(flag==null)throw new Exception("Silent installation requires --target.");Run(flag.Substring(9),!args.Contains("--no-shortcut"),!args.Contains("--no-launch"));return 0;}Application.Run(new SetupForm());return 0;}catch(Exception e){if(args.Contains("--silent")){string log=args.FirstOrDefault(x=>x.StartsWith("--log="));if(log!=null)File.WriteAllText(log.Substring(6),e.ToString());return 1;}MessageBox.Show(e.Message,"������ ��ġ ����");return 1;}}
